<?php
if(session_status()===PHP_SESSION_NONE)session_start();
require_once __DIR__.'/config/conexao.php';
require_once __DIR__.'/auth/verifica_login.php';
$aba=$_GET['aba']??'suprimentos';$valid=['suprimentos','fornecedores','demandas','compras','consumo'];if(!in_array($aba,$valid,true))$aba='suprimentos';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function nf($v){return number_format((float)$v,2,',','.');}
$fornecedores=$pdo->query("SELECT id,razao_social,nome_fantasia,cnpj,contato,telefone,email,cidade,estado,status FROM fornecedores ORDER BY COALESCE(NULLIF(nome_fantasia,''),razao_social)")->fetchAll();
$suprimentos=$pdo->query("SELECT s.*,fs.fornecedor_id,f.nome_fantasia,fs.preco_unitario,fs.prazo_entrega_dias FROM suprimentos s LEFT JOIN fornecedor_suprimentos fs ON fs.suprimento_id=s.id AND fs.fornecedor_preferencial=1 LEFT JOIN fornecedores f ON f.id=fs.fornecedor_id ORDER BY s.nome")->fetchAll();
$demandas=$pdo->query("SELECT d.id,d.numero,d.data_solicitacao,d.prioridade,d.status,s.nome suprimento_nome,dci.quantidade_solicitada quantidade,f.nome_fantasia fornecedor_nome FROM demandas_compra d JOIN demanda_compra_itens dci ON dci.demanda_id=d.id JOIN suprimentos s ON s.id=dci.suprimento_id LEFT JOIN fornecedores f ON f.id=dci.fornecedor_id ORDER BY d.id DESC")->fetchAll();
$compras=$pdo->query("SELECT c.id,c.numero,c.data_compra,c.status,COALESCE(SUM(ci.quantidade*ci.preco_unitario),0) valor_total,f.nome_fantasia,COUNT(ci.id) itens FROM compras c LEFT JOIN fornecedores f ON f.id=c.fornecedor_id LEFT JOIN compra_itens ci ON ci.compra_id=c.id GROUP BY c.id,c.numero,c.data_compra,c.status,f.nome_fantasia ORDER BY c.id DESC LIMIT 100")->fetchAll();
$consumo=$pdo->query("SELECT s.nome,s.unidade_medida,COALESCE(SUM(CASE WHEN m.tipo='CONSUMO' THEN m.quantidade ELSE 0 END),0) consumo_30 FROM suprimentos s LEFT JOIN movimentacoes_suprimentos m ON m.suprimento_id=s.id AND m.created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY s.id ORDER BY consumo_30 DESC")->fetchAll();
$baixos=array_filter($suprimentos,fn($s)=>(float)$s['estoque_atual']<=(float)$s['estoque_minimo']);
$msg=$_SESSION['mensagem_suprimentos']??'';$tipo=$_SESSION['tipo_suprimentos']??'success';unset($_SESSION['mensagem_suprimentos'],$_SESSION['tipo_suprimentos']);
require_once __DIR__.'/includes/header.php';require_once __DIR__.'/includes/sidebar.php';
?>
