<?php if($msg):?><div class="suprimentos-message <?=h($tipo)?>"><?=h($msg)?></div><?php endif;?>
<div class="estoque-kpis"><div class="metric-card"><span>Suprimentos cadastrados</span><strong><?=count($suprimentos)?></strong></div><div class="metric-card"><span>Estoque abaixo do mínimo</span><strong><?=count($baixos)?></strong></div><div class="metric-card"><span>Demandas pendentes</span><strong><?=count(array_filter($demandas,fn($d)=>in_array($d['status'],['PENDENTE','EM_COTACAO','APROVADA'],true)))?></strong></div><div class="metric-card"><span>Compras registradas</span><strong><?=count($compras)?></strong></div></div>
