<?php if($aba==='suprimentos'): ?><div class="suprimentos-form-box"><h2>Novo suprimento</h2><form method="post" action="controllers/suprimentos_controller.php"><input type="hidden" name="acao" value="salvar_suprimento"><div class="suprimentos-form-grid"><div><label>Código</label><input name="codigo" placeholder="SUP-001"></div><div><label>Nome *</label><input name="nome" required></div><div><label>Unidade *</label><select name="unidade_medida" required><option>UN</option><option>KG</option><option>G</option><option>M</option><option>M2</option><option>L</option><option>CX</option><option>PCT</option><option>ROLO</option></select></div><div><label>Estoque atual</label><input type="number" step="0.01" min="0" name="estoque_atual" value="0"></div><div><label>Estoque mínimo</label><input type="number" step="0.01" min="0" name="estoque_minimo" value="0"></div><div><label>Estoque de segurança</label><input type="number" step="0.01" min="0" name="estoque_seguranca" value="0"></div><div><label>Ponto de reposição</label><input type="number" step="0.01" min="0" name="ponto_reposicao" value="0"></div><div><label>Fornecedor preferencial</label><select name="fornecedor_id"><option value="">A definir</option><?php foreach($fornecedores as $f):?><option value="<?=$f['id']?>"><?=h($f['nome_fantasia']?:$f['razao_social'])?></option><?php endforeach;?></select></div><div><label>Preço unitário</label><input type="number" step="0.01" min="0" name="preco_unitario"></div><div><label>Prazo de entrega (dias)</label><input type="number" min="0" name="prazo_entrega_dias"></div><div class="full"><label>Descrição</label><textarea name="descricao"></textarea></div></div><button class="btn btn-pri">Salvar suprimento</button></form></div><div class="card"><div class="suprimentos-table-wrap"><table class="suprimentos-table"><thead><tr><th>Suprimento</th><th>Estoque</th><th>Mínimo</th><th>Segurança</th><th>Reposição</th><th>Fornecedor</th><th>Preço</th><th>Status</th></tr></thead><tbody><?php foreach($suprimentos as $s):$at=(float)$s['estoque_atual'];$min=(float)$s['estoque_minimo'];$rep=(float)($s['ponto_reposicao']??$min);$cl=$at<=$min?'baixo':($at<=$rep?'atencao':'ok');?><tr><td><strong><?=h($s['nome'])?></strong><small><?=h($s['codigo'])?></small></td><td><?=nf($at)?> <?=h($s['unidade_medida'])?></td><td><?=nf($min)?></td><td><?=nf($s['estoque_seguranca']??0)?></td><td><?=nf($rep)?></td><td><?=h($s['nome_fantasia']?:'A definir')?></td><td>R$ <?=nf($s['preco_unitario']??0)?></td><td><span class="estoque-tag <?=$cl?>"><?=h($cl==='baixo'?'COMPRAR':($cl==='atencao'?'ATENÇÃO':'NORMAL'))?></span></td></tr><?php endforeach;?></tbody></table></div></div>
<?php elseif($aba==='fornecedores'): ?><div class="suprimentos-form-box"><h2>Novo fornecedor</h2><form method="post" action="controllers/suprimentos_controller.php"><input type="hidden" name="acao" value="salvar_fornecedor"><div class="suprimentos-form-grid"><div><label>Razão Social *</label><input name="razao_social" required></div><div><label>Nome Fantasia</label><input name="nome_fantasia"></div><div><label>CNPJ</label><input name="cnpj"></div><div><label>Contato</label><input name="contato"></div><div><label>Telefone</label><input name="telefone"></div><div><label>E-mail</label><input type="email" name="email"></div><div><label>Cidade</label><input name="cidade"></div><div><label>Estado</label><input name="estado" maxlength="2"></div><div class="full"><label>Observações</label><textarea name="observacoes"></textarea></div></div><button class="btn btn-pri">Salvar fornecedor</button></form></div><div class="card"><div class="suprimentos-table-wrap"><table class="suprimentos-table"><thead><tr><th>Fornecedor</th><th>CNPJ</th><th>Contato</th><th>Telefone</th><th>E-mail</th><th>Local</th><th>Status</th></tr></thead><tbody><?php foreach($fornecedores as $f):?><tr><td><strong><?=h($f['nome_fantasia']?:$f['razao_social'])?></strong><small><?=h($f['razao_social'])?></small></td><td><?=h($f['cnpj'])?></td><td><?=h($f['contato'])?></td><td><?=h($f['telefone'])?></td><td><?=h($f['email'])?></td><td><?=h($f['cidade'])?><?= $f['estado']?' / '.h($f['estado']):''?></td><td><?=h($f['status'])?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php elseif($aba==='demandas'): ?><div class="suprimentos-info"><strong>Necessidade de compra</strong><br>Use o estoque mínimo, segurança e ponto de reposição como apoio. A decisão de compra continua com o usuário.</div><div class="suprimentos-form-box"><h2>Nova necessidade</h2><form method="post" action="controllers/suprimentos_controller.php"><input type="hidden" name="acao" value="salvar_demanda"><div class="suprimentos-form-grid"><div class="full"><label>Suprimento *</label><select name="suprimento_id" required><option value="">Selecione</option><?php foreach($suprimentos as $s):?><option value="<?=$s['id']?>"><?=h($s['nome'])?> — estoque <?=nf($s['estoque_atual'])?></option><?php endforeach;?></select></div><div><label>Quantidade *</label><input type="number" step="0.01" min="0.01" name="demanda_quantidade" required></div><div><label>Prioridade</label><select name="prioridade"><option>BAIXA</option><option selected>NORMAL</option><option>ALTA</option><option>URGENTE</option></select></div><div><label>Fornecedor</label><select name="demanda_fornecedor_id"><option value="">A definir</option><?php foreach($fornecedores as $f):?><option value="<?=$f['id']?>"><?=h($f['nome_fantasia']?:$f['razao_social'])?></option><?php endforeach;?></select></div><div><label>Prazo estimado</label><input type="number" min="0" name="demanda_prazo"></div><div><label>Preço estimado</label><input type="number" step="0.01" min="0" name="demanda_preco"></div><div class="full"><label>Observações</label><textarea name="demanda_observacoes"></textarea></div></div><button class="btn btn-pri">Criar necessidade</button></form></div><div class="card"><div class="suprimentos-table-wrap"><table class="suprimentos-table"><thead><tr><th>Número</th><th>Data</th><th>Suprimento</th><th>Qtd.</th><th>Prioridade</th><th>Status</th></tr></thead><tbody><?php foreach($demandas as $d):?><tr><td><?=h($d['numero'])?></td><td><?=date('d/m/Y',strtotime($d['data_solicitacao']))?></td><td><?=h($d['suprimento_nome'])?></td><td><?=nf($d['quantidade'])?></td><td><?=h($d['prioridade'])?></td><td><?=h($d['status'])?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php elseif($aba==='compras'): ?><div class="suprimentos-form-box"><h2>Registrar compra</h2><p class="form-help">A compra representa o pedido realizado ao fornecedor. O estoque só deve ser aumentado no recebimento.</p><form method="post" action="controllers/suprimentos_controller.php"><input type="hidden" name="acao" value="salvar_compra"><div class="suprimentos-form-grid"><div><label>Fornecedor *</label><select name="compra_fornecedor_id" required><option value="">Selecione</option><?php foreach($fornecedores as $f):?><option value="<?=$f['id']?>"><?=h($f['nome_fantasia']?:$f['razao_social'])?></option><?php endforeach;?></select></div><div><label>Data</label><input type="date" name="compra_data" value="<?=date('Y-m-d')?>"></div><div><label>Suprimento *</label><select name="compra_suprimento_id" required><option value="">Selecione</option><?php foreach($suprimentos as $s):?><option value="<?=$s['id']?>"><?=h($s['nome'])?></option><?php endforeach;?></select></div><div><label>Quantidade *</label><input type="number" step="0.01" min="0.01" name="compra_quantidade" required></div><div><label>Preço unitário *</label><input type="number" step="0.01" min="0" name="compra_preco" required></div><div><label>Número do pedido/NF</label><input name="compra_numero"></div></div><button class="btn btn-pri">Registrar compra</button></form></div><div class="card"><div class="suprimentos-table-wrap"><table class="suprimentos-table"><thead><tr><th>Número</th><th>Data</th><th>Fornecedor</th><th>Itens</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($compras as $c):?><tr><td><?=h($c['numero'])?></td><td><?=date('d/m/Y',strtotime($c['data_compra']))?></td><td><?=h($c['nome_fantasia']?:'—')?></td><td><?=h($c['itens'])?></td><td>R$ <?=nf($c['valor_total'])?></td><td><?=h($c['status'])?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php else: ?><div class="suprimentos-form-box"><h2>Registrar consumo</h2><form method="post" action="controllers/suprimentos_controller.php"><input type="hidden" name="acao" value="registrar_consumo"><div class="suprimentos-form-grid"><div><label>Suprimento *</label><select name="suprimento_id" required><option value="">Selecione</option><?php foreach($suprimentos as $s):?><option value="<?=$s['id']?>"><?=h($s['nome'])?> — estoque <?=nf($s['estoque_atual'])?></option><?php endforeach;?></select></div><div><label>Quantidade *</label><input type="number" step="0.01" min="0.01" name="quantidade" required></div><div class="full"><label>Motivo</label><input name="motivo" placeholder="Ex.: embalagem, produção, expedição"></div></div><button class="btn btn-pri">Registrar consumo</button></form></div><div class="card"><div class="section-header"><div><h2>Consumo de suprimentos — últimos 30 dias</h2><p>Base para perceber ritmo de consumo e planejar reposição.</p></div></div><div class="suprimentos-table-wrap"><table class="suprimentos-table"><thead><tr><th>Suprimento</th><th>Unidade</th><th>Consumo em 30 dias</th><th>Média diária</th></tr></thead><tbody><?php foreach($consumo as $c):?><tr><td><?=h($c['nome'])?></td><td><?=h($c['unidade_medida'])?></td><td><?=nf($c['consumo_30'])?></td><td><?=nf((float)$c['consumo_30']/30)?></td></tr><?php endforeach;?></tbody></table></div></div><?php endif; ?>
</div></div></div><?php include __DIR__.'/includes/footer.php'; ?>
